    string line;
    getline(cin, line);
    {
        stringstream ss(line);
        int x;
        while(ss >> x) nums.push_back(x);
    }

    long long take = 0, skip = 0;
    for(int x : nums){
        long long newTake = skip + x;
        long long newSkip = max(skip, take);
        take = newTake;
        skip = newSkip;
    }
    cout << max(take, skip) << "\n";
    return 0;
}

import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        line = (line == null) ? "" : line.trim();
        int[] nums;
        if (line.isEmpty()) {
            nums = new int[0];
        } else {
            String[] parts = line.split("\\s+");
            nums = new int[parts.length];
            for (int i = 0; i < parts.length; i++) nums[i] = Integer.parseInt(parts[i]);
        }

        long take = 0, skip = 0;
        for (int x : nums) {
            long newTake = skip + x;
            long newSkip = Math.max(skip, take);
            take = newTake;
            skip = newSkip;
        }
        System.out.println(Math.max(take, skip));
    }
}

const readline = require('readline');
const rl = readline.createInterface({ input: process.stdin, terminal: false });
let lines = [];
rl.on('line', (l) => lines.push(l));
rl.on('close', () => {
    const nums = (lines[0] || '').trim() === '' ? [] : lines[0].trim().split(/\s+/).map(Number);

    let take = 0, skip = 0;
    for (const x of nums) {
        const newTake = skip + x;
        const newSkip = Math.max(skip, take);
        take = newTake;
        skip = newSkip;
    }
    console.log(Math.max(take, skip));
});
